"""Standalone HTML build-lineage visualization."""
from html import escape


def render(baseline: dict, tampered: dict, lineage: dict, original: dict, next_run: dict) -> str:
    badges = ''.join(f'<span class="chip">{escape(x)}</span>' for x in tampered['issues'])
    changes = ''.join(f'<li>{escape(kind)}: <strong>{escape(", ".join(lineage[kind]) or "none")}</strong></li>' for kind in ('added','modified','removed'))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Provenance Vault · Run Lineage</title><style>
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#121921;color:#f4f7fb;font:16px/1.55 system-ui,sans-serif}}main{{max-width:1000px;padding:clamp(20px,5vw,60px);margin:auto}}.eyebrow{{color:#e7ce8e;text-transform:uppercase;letter-spacing:.16em;font-weight:750;font-size:.78rem}}h1{{font-size:clamp(2rem,5vw,3.8rem);line-height:1.1;margin:12px 0}}p{{color:#c5d0dd;max-width:70ch}}.cols{{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px;margin:30px 0}}.card,.panel{{border:1px solid #3b5267;border-radius:16px;background:#1c2a37;padding:23px}}.state{{font-size:2rem;font-weight:800}}.good{{color:#a3e3b4}}.bad{{color:#ffbbac}}.panel{{margin:20px 0}}.node{{border-radius:12px;border:1px solid #5b7788;background:#213746;padding:18px;margin:16px 0}}.arrow{{font-size:2rem;color:#e7ce8e;text-align:center}}code{{color:#dceabb;overflow-wrap:anywhere}}.chip{{display:inline-block;border-radius:14px;margin:4px;padding:6px 10px;background:#5c3540;border:1px solid #a56470}}footer{{font-size:.85rem;margin-top:35px;color:#b6c2cf}}ul{{padding-left:20px}}</style></head><body><main>
<div class="eyebrow">Reproducible artifacts / toy attestation</div><h1>AI Provenance Vault</h1><p>Capture a SHA-256 file manifest, sign it with an educational HMAC demo key, verify a before-and-after tampering experiment, and trace a parent-linked artifact version. The report contains no signing secret.</p>
<div class="cols"><div class="card"><div>Untouched artifact set</div><div class="state good">{'PASS' if baseline['ok'] else 'FAIL'}</div><p>{baseline['file_count']} files verified</p></div><div class="card"><div>Modified artifact set</div><div class="state bad">{'PASS' if tampered['ok'] else 'FAIL'}</div><p>Expected failure after a file mutation</p></div></div>
<section class="panel"><h2>Tamper signals</h2>{badges}</section><section class="panel"><h2>Build lineage</h2><div class="node"><strong>Run {escape(original['run_id'])}</strong><p>SHA-256 Merkle root: <code>{escape(original['merkle_root'])}</code></p></div><div class="arrow" aria-label="Child run">↓</div><div class="node"><strong>Run {escape(next_run['run_id'])}</strong><p>SHA-256 Merkle root: <code>{escape(next_run['merkle_root'])}</code></p></div><h3>Changed artifacts</h3><ul>{changes}</ul></section>
<footer>HMAC requires a shared secret, so its signatures do not provide independent public verification or a trusted build provenance guarantee. Local files and example keys are synthetic. Not SLSA, Sigstore, or cloud supply-chain attestation.</footer></main></body></html>'''
